    const char *iext[2] = { "VK_KHR_surface", surf_ext };
    VkInstanceCreateInfo ici = { 1, 0, 0, &app, 0, 0, 2, iext };
    if (tbvk_CreateInstance(&ici, 0, &tb_vk.inst)) return 0;
