    { const char * tb_v3534 = "TB_API int tb_gin = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3534; }
    { const char * tb_v3535 = "// TB_GSLOTS наборов памяти по кругу: пока видеокарта рисует один кадр, программа уже пишет следующий\n"; *(const char * *)tb_grow(v_lines) = tb_v3535; }
