    { const char * tb_v3553 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3553; }
    { const char * tb_v3554 = "TB_API void tb_gpu_say(const char *what) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3554; }
    { const char * tb_v3555 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3555; }
    { const char * tb_v3556 = "    if ((e && e[0] == '1') || tb_gpu_check) fprintf(stderr, \"окно: рисует %s\\n\", what);\n"; *(const char * *)tb_grow(v_lines) = tb_v3556; }
    { const char * tb_v3557 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3557; }
    { const char * tb_v3558 = "TB_API void tb_gpu_report(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3558; }
    { const char * tb_v3559 = "    fprintf(stderr, \"TB_GPU_CHECK: кадров %lld, разошлось %lld\\n\", tb_gpu_frames, tb_gpu_bad);\n"; *(const char * *)tb_grow(v_lines) = tb_v3559; }
    { const char * tb_v3560 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3560; }
    { const char * tb_v3561 = "// сверить кадр видеокарты с кадром процессора (видны только младшие 24 бита цвета)\n"; *(const char * *)tb_grow(v_lines) = tb_v3561; }
    { const char * tb_v3562 = "TB_API void tb_gpu_compare(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3562; }
    { const char * tb_v3563 = "    if (!tb_gpu_back) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3563; }
    { const char * tb_v3564 = "    tb_gpu_frames++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3564; }
    { const char * tb_v3565 = "    long long n = (long long)tb_gw * tb_gh, bad = 0, first = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3565; }
    { const char * tb_v3566 = "    for (long long i = 0; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3566; }
    { const char * tb_v3567 = "        if (((tb_gpu_back[i] ^ tb_px[i]) & 0xFFFFFF) != 0) { if (first < 0) first = i; bad++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3567; }
    { const char * tb_v3568 = "    if (bad) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3568; }
    { const char * tb_v3569 = "        tb_gpu_bad++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3569; }
    { const char * tb_v3570 = "        if (tb_gpu_bad <= 5)\n"; *(const char * *)tb_grow(v_lines) = tb_v3570; }
    { const char * tb_v3571 = "            fprintf(stderr, \"TB_GPU_CHECK: кадр %lld: не совпало точек %lld, первая x=%lld y=%lld: видеокарта %06x, процессор %06x\\n\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3571; }
    { const char * tb_v3572 = "                tb_gpu_frames, bad, first % tb_gw, first / tb_gw, tb_gpu_back[first] & 0xFFFFFF, tb_px[first] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v3572; }
    { const char * tb_v3573 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3573; }
    { const char * tb_v3574 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3574; }
    { const char * tb_v3575 = "TB_INL void tb_gpu_add(long long x0, long long y0, long long x1, long long y1, long long ox, long long oy, uint32_t c, uint32_t m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3575; }
    { const char * tb_v3576 = "    if (tb_gin == TB_GI_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3576; }
    { const char * tb_v3577 = "    tb_ginst *g = &tb_gi[tb_gin++];\n"; *(const char * *)tb_grow(v_lines) = tb_v3577; }
    { const char * tb_v3578 = "    g->x0 = (int32_t)x0; g->y0 = (int32_t)y0; g->x1 = (int32_t)x1; g->y1 = (int32_t)y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3578; }
    { const char * tb_v3579 = "    g->ox = (int32_t)ox; g->oy = (int32_t)oy; g->c = c; g->m = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v3579; }
    { const char * tb_v3580 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3580; }
    { const char * tb_v3581 = "// прямоугольник: обрезан окном; соседние полоски одного цвета склеиваются (линии, точки по одной)\n"; *(const char * *)tb_grow(v_lines) = tb_v3581; }
    { const char * tb_v3582 = "TB_API void tb_gpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3582; }
    { const char * tb_v3583 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v3583; }
    { const char * tb_v3584 = "    if (x0 >= x1 || y0 >= y1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3584; }
    { const char * tb_v3585 = "    uint32_t cc = (uint32_t)c & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v3585; }
    { const char * tb_v3586 = "    if (tb_gin > 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3586; }
    { const char * tb_v3587 = "        tb_ginst *g = &tb_gi[tb_gin - 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v3587; }
    { const char * tb_v3588 = "        if (g->m == 0 && g->c == cc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3588; }
    { const char * tb_v3589 = "            if (g->y0 == y0 && g->y1 == y1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3589; }
    { const char * tb_v3590 = "                if (g->x1 == x0) { g->x1 = (int32_t)x1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3590; }
    { const char * tb_v3591 = "                if (g->x0 == x1) { g->x0 = (int32_t)x0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3591; }
    { const char * tb_v3592 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v3592; }
    { const char * tb_v3593 = "            if (g->x0 == x0 && g->x1 == x1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3593; }
    { const char * tb_v3594 = "                if (g->y1 == y0) { g->y1 = (int32_t)y1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3594; }
    { const char * tb_v3595 = "                if (g->y0 == y1) { g->y0 = (int32_t)y0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3595; }
    { const char * tb_v3596 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v3596; }
    { const char * tb_v3597 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3597; }
    { const char * tb_v3598 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3598; }
    { const char * tb_v3599 = "    tb_gpu_add(x0, y0, x1, y1, 0, 0, cc, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3599; }
    { const char * tb_v3600 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3600; }
    { const char * tb_v3601 = "TB_API void tb_gpu_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3601; }
    { const char * tb_v3602 = "    if (r < 0 || cx + r < 0 || cy + r < 0 || cx - r >= tb_gw || cy - r >= tb_gh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3602; }
    { const char * tb_v3603 = "    if (r <= 16384) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3603; }
    { const char * tb_v3604 = "        long long x0 = cx - r < 0 ? 0 : cx - r, y0 = cy - r < 0 ? 0 : cy - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v3604; }
    { const char * tb_v3605 = "        long long x1 = cx + r + 1 > tb_gw ? tb_gw : cx + r + 1, y1 = cy + r + 1 > tb_gh ? tb_gh : cy + r + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3605; }
    { const char * tb_v3606 = "        tb_gpu_add(x0, y0, x1, y1, cx, cy, (uint32_t)c & 0xFFFFFF, (1u << 30) | (uint32_t)r);\n"; *(const char * *)tb_grow(v_lines) = tb_v3606; }
    { const char * tb_v3607 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3607; }
    { const char * tb_v3608 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3608; }
    { const char * tb_v3609 = "    // огромный круг: по строкам, полосками (то же правило i*i + j*j <= r*r + r)\n"; *(const char * *)tb_grow(v_lines) = tb_v3609; }
    { const char * tb_v3610 = "    long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v3610; }
    { const char * tb_v3611 = "    for (long long j = ja; j <= jb; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3611; }
    { const char * tb_v3612 = "        long long rest = r * r + r - j * j, i = (long long)sqrt((double)rest);\n"; *(const char * *)tb_grow(v_lines) = tb_v3612; }
    { const char * tb_v3613 = "        while (i * i > rest) i--;\n"; *(const char * *)tb_grow(v_lines) = tb_v3613; }
    { const char * tb_v3614 = "        while ((i + 1) * (i + 1) <= rest) i++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3614; }
    { const char * tb_v3615 = "        tb_gpu_rect(cx - i, cy + j, 2 * i + 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v3615; }
    { const char * tb_v3616 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3616; }
    { const char * tb_v3617 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3617; }
    { const char * tb_v3618 = "TB_API void tb_gpu_image(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3618; }
    { const char * tb_v3619 = "    tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v3619; }
    { const char * tb_v3620 = "    if (x >= tb_gw || y >= tb_gh || x + im->w <= 0 || y + im->h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3620; }
    { const char * tb_v3621 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;\n"; *(const char * *)tb_grow(v_lines) = tb_v3621; }
    { const char * tb_v3622 = "    long long x1 = x + im->w > tb_gw ? tb_gw : x + im->w, y1 = y + im->h > tb_gh ? tb_gh : y + im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v3622; }
    { const char * tb_v3623 = "    tb_gpu_add(x0, y0, x1, y1, x, y, im->off, (3u << 30) | (uint32_t)im->w);\n"; *(const char * *)tb_grow(v_lines) = tb_v3623; }
    { const char * tb_v3624 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3624; }
    { const char * tb_v3625 = "// треугольник: m = 1 (вид 0, но не прямоугольник); в q и o — три угла, уже по кругу «как надо» (tb_tri_prep).\n"; *(const char * *)tb_grow(v_lines) = tb_v3625; }
    { const char * tb_v3626 = "// Квадрат вокруг строит шейдер, а какие точки внутри — решает то же правило, что на процессоре (tb_tri_in)\n"; *(const char * *)tb_grow(v_lines) = tb_v3626; }
    { const char * tb_v3627 = "TB_API void tb_gpu_triangle(const long long *t, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3627; }
    { const char * tb_v3628 = "    tb_gpu_add(t[0], t[1], t[2], t[3], t[4], t[5], (uint32_t)c & 0xFFFFFF, 1u);\n"; *(const char * *)tb_grow(v_lines) = tb_v3628; }
    { const char * tb_v3629 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3629; }
    { const char * tb_v3630 = "TB_API void tb_gpu_glyph(long long x, long long y, int g, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3630; }
    { const char * tb_v3631 = "    if (x >= tb_gw || y >= tb_gh || x + 8 * size <= 0 || y + 16 * size <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3631; }
    { const char * tb_v3632 = "    if (size >= (1 << 22) || x < -(1LL << 30) || y < -(1LL << 30)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3632; }
    { const char * tb_v3633 = "        for (int row = 0; row < 16; row++) for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3633; }
    { const char * tb_v3634 = "            if (tb_font[g][row] & (0x80 >> col)) tb_gpu_rect(x + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v3634; }
    { const char * tb_v3635 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3635; }
    { const char * tb_v3636 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3636; }
    { const char * tb_v3637 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;\n"; *(const char * *)tb_grow(v_lines) = tb_v3637; }
    { const char * tb_v3638 = "    long long x1 = x + 8 * size > tb_gw ? tb_gw : x + 8 * size, y1 = y + 16 * size > tb_gh ? tb_gh : y + 16 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v3638; }
    { const char * tb_v3639 = "    tb_gpu_add(x0, y0, x1, y1, x, y, (uint32_t)c & 0xFFFFFF, (2u << 30) | ((uint32_t)g << 22) | (uint32_t)size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3639; }
    { const char * tb_v3640 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3640; }
