    { const char * tb_v3644 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3644; }
    { const char * tb_v3645 = "// ---------- Vulkan (Linux и Windows) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3645; }
    { const char * tb_v3646 = "// Свои описания Vulkan (только то, что нужно): программе не нужны заголовки Vulkan,\n"; *(const char * *)tb_grow(v_lines) = tb_v3646; }
    { const char * tb_v3647 = "// а сама библиотека Vulkan грузится при запуске (dlopen) — нет её, рисуем на процессоре.\n"; *(const char * *)tb_grow(v_lines) = tb_v3647; }
    { const char * tb_v3648 = "#if defined(_WIN32) && !defined(_WIN64)\n"; *(const char * *)tb_grow(v_lines) = tb_v3648; }
