    { const char * tb_v5106 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5106; }
    { const char * tb_v5107 = "TB_API long long tb_window_w(void) { if (tb_px && !tb_resizable) { tb_resizable = 1; tb_gfx_resizable(); } return tb_gw; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5107; }
