    { const char * tb_v5111 = "TB_API long long tb_fps_want = -1, tb_fps_v = 0, tb_fps_n = 0, tb_fps_t0 = 0, tb_last_us = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5111; }
    { const char * tb_v5112 = "TB_API void tb_set_fps(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5112; }
    { const char * tb_v5113 = "    if (n < 0) n = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5113; }
    { const char * tb_v5114 = "    tb_fps_want = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v5114; }
