    { const char * tb_v5119 = "TB_API long long tb_fps(void) { return tb_fps_v ? tb_fps_v : tb_frame_ms_v > 0 ? (long long)(1000 / tb_frame_ms_v) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5119; }
    { const char * tb_v5120 = "// показать кадр, принять клавиши и мышь, держать частоту кадров; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v5120; }
    { const char * tb_v5121 = "TB_API int tb_window_alive(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5121; }
    { const char * tb_v5122 = "    if (!tb_px || tb_gclosed) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5122; }
    { const char * tb_v5123 = "    tb_gfx_events();\n"; *(const char * *)tb_grow(v_lines) = tb_v5123; }
    { const char * tb_v5124 = "    tb_apply_resize();\n"; *(const char * *)tb_grow(v_lines) = tb_v5124; }
    { const char * tb_v5125 = "    // TB_FPS_FREE=1 — без ограничения (для замеров скорости), как set_fps(0)\n"; *(const char * *)tb_grow(v_lines) = tb_v5125; }
    { const char * tb_v5126 = "    static int free_fps = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5126; }
    { const char * tb_v5127 = "    if (free_fps < 0) free_fps = getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5127; }
    { const char * tb_v5128 = "    long long now = tb_time_us(), period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5128; }
    { const char * tb_v5129 = "    if (!tb_last_us) tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v5129; }
    { const char * tb_v5130 = "    if (free_fps || tb_fps_want == 0) period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5130; }
    { const char * tb_v5131 = "    else if (tb_fps_want > 0) period = 1000000 / tb_fps_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v5131; }
    { const char * tb_v5132 = "    // как у экрана: видеокарта сама ждёт обновления экрана (60 Гц — 60 кадров, 120 Гц — 120);\n"; *(const char * *)tb_grow(v_lines) = tb_v5132; }
    { const char * tb_v5133 = "    // кадр пришёл быстрее 4 мс — экран частоту не держит, держим сами 60 кадров в секунду\n"; *(const char * *)tb_grow(v_lines) = tb_v5133; }
    { const char * tb_v5134 = "    else if (!tb_gpu_on || now - tb_last_us < 4000) period = 16667;\n"; *(const char * *)tb_grow(v_lines) = tb_v5134; }
    { const char * tb_v5135 = "    if (period && now - tb_last_us < period) { usleep((useconds_t)(period - (now - tb_last_us))); now = tb_time_us(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v5135; }
    { const char * tb_v5136 = "    tb_frame_ms_v = (now - tb_last_us) / 1000.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5136; }
    { const char * tb_v5137 = "    tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v5137; }
