    { const char * tb_v5139 = "    tb_fps_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5139; }
    { const char * tb_v5140 = "    if (now - tb_fps_t0 >= 1000000) { tb_fps_v = tb_fps_n * 1000000 / (now - tb_fps_t0); tb_fps_n = 0; tb_fps_t0 = now; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5140; }
    { const char * tb_v5141 = "    tb_last_frame = now / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v5141; }
    { const char * tb_v5142 = "    return !tb_gclosed;\n"; *(const char * *)tb_grow(v_lines) = tb_v5142; }
    { const char * tb_v5143 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5143; }
