    { const char * tb_v5145 = "    if (tb_px && x >= 0 && y >= 0 && x < tb_gw && y < tb_gh) tb_px[y * tb_gw + x] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v5145; }
    { const char * tb_v5146 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5146; }
    { const char * tb_v5147 = "// на видеокарте фигуры записываются (tb_gpu_*), на процессоре — рисуются сразу в tb_px.\n"; *(const char * *)tb_grow(v_lines) = tb_v5147; }
    { const char * tb_v5148 = "// TB_GPU_CHECK=1: и то и другое, кадры сверяются\n"; *(const char * *)tb_grow(v_lines) = tb_v5148; }
