    { const char * tb_v5151 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5151; }
    { const char * tb_v5152 = "    if (tb_gpu_on) { tb_gin = 0; tb_gpu_rect(0, 0, tb_gw, tb_gh, c); }   // всё прежнее закрашено\n"; *(const char * *)tb_grow(v_lines) = tb_v5152; }
    { const char * tb_v5153 = "    if (TB_CPU_DRAW) for (long long i = 0; i < (long long)tb_gw * tb_gh; i++) tb_px[i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v5153; }
    { const char * tb_v5154 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5154; }
    { const char * tb_v5155 = "TB_API void tb_draw_pixel(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5155; }
    { const char * tb_v5156 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5156; }
