    { const char * tb_v5160 = "TB_API void tb_cpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5160; }
    { const char * tb_v5161 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v5161; }
    { const char * tb_v5162 = "    for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v5162; }
    { const char * tb_v5163 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5163; }
    { const char * tb_v5164 = "TB_API void tb_draw_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5164; }
    { const char * tb_v5165 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5165; }
