    { const char * tb_v5167 = "    if (TB_CPU_DRAW) tb_cpu_rect(x, y, w, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5167; }
    { const char * tb_v5168 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5168; }
    { const char * tb_v5169 = "TB_API void tb_draw_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5169; }
    { const char * tb_v5170 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5170; }
    { const char * tb_v5171 = "    if (tb_gpu_on) tb_gpu_circle(cx, cy, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5171; }
    { const char * tb_v5172 = "    if (TB_CPU_DRAW) {   // только строки и столбцы внутри окна: огромный круг не перебирает r*r точек\n"; *(const char * *)tb_grow(v_lines) = tb_v5172; }
    { const char * tb_v5173 = "        long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v5173; }
    { const char * tb_v5174 = "        long long ia = -r > -cx ? -r : -cx, ib = r < tb_gw - 1 - cx ? r : tb_gw - 1 - cx;\n"; *(const char * *)tb_grow(v_lines) = tb_v5174; }
    { const char * tb_v5175 = "        for (long long j = ja; j <= jb; j++) for (long long i = ia; i <= ib; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v5175; }
    { const char * tb_v5176 = "            if (i * i + j * j <= r * r + r) tb_put(cx + i, cy + j, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5176; }
    { const char * tb_v5177 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5177; }
    { const char * tb_v5178 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5178; }
    { const char * tb_v5179 = "TB_API void tb_draw_line(long long x0, long long y0, long long x1, long long y1, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5179; }
    { const char * tb_v5180 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5180; }
    { const char * tb_v5181 = "    long long dx = x1 > x0 ? x1 - x0 : x0 - x1, dy = y1 > y0 ? y0 - y1 : y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5181; }
    { const char * tb_v5182 = "    long long sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1, e = dx + dy;\n"; *(const char * *)tb_grow(v_lines) = tb_v5182; }
    { const char * tb_v5183 = "    int gpu = tb_gpu_on, cpu = TB_CPU_DRAW;\n"; *(const char * *)tb_grow(v_lines) = tb_v5183; }
    { const char * tb_v5184 = "    while (1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5184; }
    { const char * tb_v5185 = "        if (gpu) tb_gpu_rect(x0, y0, 1, 1, c);   // соседние точки склеятся в полоски\n"; *(const char * *)tb_grow(v_lines) = tb_v5185; }
    { const char * tb_v5186 = "        if (cpu) tb_put(x0, y0, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5186; }
    { const char * tb_v5187 = "        if (x0 == x1 && y0 == y1) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v5187; }
    { const char * tb_v5188 = "        long long e2 = 2 * e;\n"; *(const char * *)tb_grow(v_lines) = tb_v5188; }
    { const char * tb_v5189 = "        if (e2 >= dy) { e += dy; x0 += sx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5189; }
    { const char * tb_v5190 = "        if (e2 <= dx) { e += dx; y0 += sy; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5190; }
    { const char * tb_v5191 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5191; }
    { const char * tb_v5192 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5192; }
    { const char * tb_v5193 = "// Треугольник. Правило точек одно для процессора и видеокарты (кадры совпадают точка в точку):\n"; *(const char * *)tb_grow(v_lines) = tb_v5193; }
    { const char * tb_v5194 = "// точка (x, y) берётся по своему центру (x + 0.5, y + 0.5); углы обходятся так, что площадь > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5194; }
    { const char * tb_v5195 = "// для каждой стороны a→b: e = (bx-ax)*(2y+1-2ay) - (by-ay)*(2x+1-2ax); точка внутри, если e > 0\n"; *(const char * *)tb_grow(v_lines) = tb_v5195; }
    { const char * tb_v5196 = "// для всех трёх, а если e == 0 — только на сторонах с by > ay или (by == ay и bx < ax).\n"; *(const char * *)tb_grow(v_lines) = tb_v5196; }
    { const char * tb_v5197 = "// Так у двух соседних треугольников общая сторона рисуется ровно один раз.\n"; *(const char * *)tb_grow(v_lines) = tb_v5197; }
    { const char * tb_v5198 = "// Углы ограничены ±8192 точек — тогда в шейдере (32-битные числа) ничего не переполняется.\n"; *(const char * *)tb_grow(v_lines) = tb_v5198; }
    { const char * tb_v5199 = "TB_INL long long tb_tri_clamp(long long v) { return v < -8192 ? -8192 : v > 8192 ? 8192 : v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5199; }
    { const char * tb_v5200 = "// t = x1 y1 x2 y2 x3 y3; 0 — рисовать нечего (площадь 0 или целиком вне окна)\n"; *(const char * *)tb_grow(v_lines) = tb_v5200; }
    { const char * tb_v5201 = "TB_INL int tb_tri_prep(long long *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5201; }
    { const char * tb_v5202 = "    for (int i = 0; i < 6; i++) t[i] = tb_tri_clamp(t[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v5202; }
    { const char * tb_v5203 = "    long long a2 = (t[2] - t[0]) * (t[5] - t[1]) - (t[3] - t[1]) * (t[4] - t[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v5203; }
    { const char * tb_v5204 = "    if (a2 == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5204; }
    { const char * tb_v5205 = "    if (a2 < 0) { long long x = t[2], y = t[3]; t[2] = t[4]; t[3] = t[5]; t[4] = x; t[5] = y; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5205; }
    { const char * tb_v5206 = "    long long x0 = t[0], x1 = t[0], y0 = t[1], y1 = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v5206; }
    { const char * tb_v5207 = "    for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5207; }
    { const char * tb_v5208 = "        if (t[i] < x0) x0 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v5208; }
    { const char * tb_v5209 = "        if (t[i] > x1) x1 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v5209; }
    { const char * tb_v5210 = "        if (t[i + 1] < y0) y0 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v5210; }
    { const char * tb_v5211 = "        if (t[i + 1] > y1) y1 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v5211; }
    { const char * tb_v5212 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5212; }
    { const char * tb_v5213 = "    return !(x1 < 0 || y1 < 0 || x0 > tb_gw || y0 > tb_gh);\n"; *(const char * *)tb_grow(v_lines) = tb_v5213; }
    { const char * tb_v5214 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5214; }
    { const char * tb_v5215 = "TB_INL int tb_tri_edge(long long ax, long long ay, long long bx, long long by, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5215; }
    { const char * tb_v5216 = "    long long ex = bx - ax, ey = by - ay, e = ex * (2 * y + 1 - 2 * ay) - ey * (2 * x + 1 - 2 * ax);\n"; *(const char * *)tb_grow(v_lines) = tb_v5216; }
    { const char * tb_v5217 = "    return e > 0 || (e == 0 && (ey > 0 || (ey == 0 && ex < 0)));\n"; *(const char * *)tb_grow(v_lines) = tb_v5217; }
    { const char * tb_v5218 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5218; }
    { const char * tb_v5219 = "TB_API void tb_draw_triangle(long long x1, long long y1, long long x2, long long y2, long long x3, long long y3, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5219; }
    { const char * tb_v5220 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5220; }
    { const char * tb_v5221 = "    long long t[6] = { x1, y1, x2, y2, x3, y3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v5221; }
    { const char * tb_v5222 = "    if (!tb_tri_prep(t)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5222; }
    { const char * tb_v5223 = "    if (tb_gpu_on) tb_gpu_triangle(t, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5223; }
    { const char * tb_v5224 = "    if (TB_CPU_DRAW) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5224; }
    { const char * tb_v5225 = "        long long xa = t[0], xb = t[0], ya = t[1], yb = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v5225; }
