    { const char * tb_v5263 = "    long long cx = x;\n"; *(const char * *)tb_grow(v_lines) = tb_v5263; }
    { const char * tb_v5264 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5264; }
