    { const char * tb_v5266 = "        if (u >= 0x80) {   // UTF-8: собрать букву из 2–4 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v5266; }
    { const char * tb_v5267 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5267; }
    { const char * tb_v5268 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v5268; }
