    { const char * tb_v5270 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v5270; }
    { const char * tb_v5271 = "        if (u == 0x2013 || u == 0x2014) u = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v5271; }
    { const char * tb_v5272 = "        if (u == 0xD7) u = 'x';   // × как x (размер окна 640×400)\n"; *(const char * *)tb_grow(v_lines) = tb_v5272; }
    { const char * tb_v5273 = "        if (u == 0xAB || u == 0xBB || u == 0x201C || u == 0x201D) u = '\"';\n"; *(const char * *)tb_grow(v_lines) = tb_v5273; }
    { const char * tb_v5274 = "        if (u == '\\n') { cx = x; y += 16 * size; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5274; }
    { const char * tb_v5275 = "        int g = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5275; }
